lookup.day_rate:
// Employment Act 1955 s.60I(1a): a monthly rate over 26, fixed cash allowances included. A piece rate has no day rate: s.60I(1c) needs the preceding wage period.
// proration_basis CALENDAR_DAYS, s.18A (AGC reprint): monthly wages / number of days of the particular wage period x days eligible.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const hours = Number(get(terms, 'normal_hours_per_day', ctx.lookup.normal_hours_per_day));
if (unit === 'DAILY') return amount;
if (unit === 'HOURLY') return amount * hours;
if (unit !== 'MONTHLY') return 0;
if (!ctx.lookup.fixed_allowances_in_ordinary_pay) return amount / ctx.lookup.monthly_divisor;
const fixed = Object.entries(get(terms, 'allowances', {})).reduce(
	(total, entry) =>
		get(entry[1], 'variability', 'FIXED') === 'VARIABLE' ||
		ctx.lookup.excluded_allowances.includes(entry[0])
			? total
			: total + Number(get(entry[1], 'amount', 0)),
	0
);
return (amount + fixed) / ctx.lookup.monthly_divisor;
